LANGS = ("ko", "es", "pt", "de", "fr")

def glossary():
    table = {code: {} for code in LANGS}
    for row in ROWS:
        english = row[0]
        for code, value in zip(LANGS, row[1:]):
            table[code][english] = value
    return table
